/// `${input}` or `${input.key}`: a reference to the workflow input, resolved when the step runs.
pub fn input(key: Option<&str>) -> Value {
    Value::String(match key {
        Some(k) => format!("${{input.{}}}", k),
        None => "${input}".to_string(),
    })
}

/// `${steps.<name>.output[.key]}`: a reference to a finished step's output.
pub fn output(step_name: &str, key: Option<&str>) -> Value {
    Value::String(match key {
        Some(k) => format!("${{steps.{}.output.{}}}", step_name, k),
        None => format!("${{steps.{}.output}}", step_name),
    })
}

/// `${update.input}` or `${update.input.key}`: the input of the update being handled, for an update's `validate`,
/// `input` and `result` (`Workflow::update`). The engine resolves it.
pub fn update_input(key: Option<&str>) -> Value {
    Value::String(match key {
        Some(k) => format!("${{update.input.{}}}", k),
        None => "${update.input}".to_string(),
    })
}

/// Any dotted path below `input` or `steps`, e.g. `reference("steps.a.output.total")`.
pub fn reference(path: &str) -> Value {
    let clean = path.trim();
    if clean.starts_with("${") && clean.ends_with('}') {
        Value::String(clean.to_string())
    } else {
        Value::String(format!("${{{}}}", clean))
    }
}

/// The `${...}` references a step input makes (a blueprint sends these, never the literal values around them).
pub fn collect_references(spec: &Value, found: &mut Vec<String>) {
    match spec {
        Value::String(s) if s.starts_with("${") && s.ends_with('}') => {
            if !found.contains(s) {
                found.push(s.clone());
            }
        }
        Value::Array(items) => items.iter().for_each(|v| collect_references(v, found)),
        Value::Object(map) => map.values().for_each(|v| collect_references(v, found)),
        _ => {}
    }
}

fn lookup<'a>(mut cur: &'a Value, dotted: &str) -> Option<&'a Value> {
    for part in dotted.split('.').filter(|p| !p.is_empty()) {
        cur = cur.get(part)?;
    }
    Some(cur)
}

/// Replaces every reference in `spec` with its value. A `null` spec is the workflow input.
pub fn resolve_references(spec: &Value, workflow_input: &Value, checkpoints: &Map) -> Value {
    match spec {
        Value::Null => workflow_input.clone(),
        Value::String(s) if s.starts_with("${") && s.ends_with('}') => {
            let path = &s[2..s.len() - 1];
            if path == "input" {
                return workflow_input.clone();
            }
            if let Some(rest) = path.strip_prefix("input.") {
                return lookup(workflow_input, rest).cloned().unwrap_or(Value::Null);
            }
            if path == "steps" {
                return Value::Object(checkpoints.clone());
            }
            if let Some(rest) = path.strip_prefix("steps.") {
                let mut parts = rest.splitn(3, '.');
                let step = parts.next().unwrap_or("");
                let out = checkpoints.get(step).cloned().unwrap_or(Value::Null);
                let _output = parts.next();
                return match parts.next() {
                    Some(k) => lookup(&out, k).cloned().unwrap_or(Value::Null),
                    None => out,
                };
            }
            Value::String(s.clone())
        }
        Value::Object(m) => Value::Object(m.iter().map(|(k, v)| (k.clone(), resolve_references(v, workflow_input, checkpoints))).collect()),
        Value::Array(a) => Value::Array(a.iter().map(|v| resolve_references(v, workflow_input, checkpoints)).collect()),
        other => other.clone(),
    }
}

fn step_dependencies(spec: &Value, out: &mut Vec<String>) {
    match spec {
        Value::String(s) if s.starts_with("${steps.") => {
            if let Some(name) = s[8..s.len().saturating_sub(1)].split('.').next() {
                if !name.is_empty() && !out.iter().any(|d| d == name) {
                    out.push(name.to_string());
                }
            }
        }
        Value::Object(m) => m.values().for_each(|v| step_dependencies(v, out)),
        Value::Array(a) => a.iter().for_each(|v| step_dependencies(v, out)),
        _ => {}
    }
}

fn is_reference(spec: &Value) -> bool {
    matches!(spec, Value::String(s) if s.starts_with("${") && s.ends_with('}'))
}

/// A child's or continued run's input as the engine resolves it: references (`input`, `output`, `reference`) in
/// objects and arrays. A literal value panics when the blueprint is built: compute a constant in a step and refer to
/// its output.
fn template(spec: &Value, at: &str) -> Value {
    match spec {
        Value::Object(m) => Value::Object(m.iter().map(|(k, v)| (k.clone(), template(v, &format!("{}.{}", at, k)))).collect()),
        Value::Array(a) => Value::Array(a.iter().enumerate().map(|(i, v)| template(v, &format!("{}[{}]", at, i))).collect()),
        v if is_reference(v) => v.clone(),
        other => panic!("{}: {} is not a reference; the engine resolves this input, so only references are sent", at, other),
    }
}

