/// The verdict of a `rate_limit` call: whether a token was granted, and when to retry if not.
#[derive(Debug, Clone, serde::Deserialize)]
pub struct RateLimitResult {
    pub allowed: bool,
    pub retry_after_ms: i64,
}

/// Options of a workflow step. `after`, `timeout_ms`, `heartbeat_ms` and `schedule_to_start_ms` are enforced by the
/// engine (a run the worker conducts itself ignores them).
pub struct StepOptions {
    pub input: Value,
    pub retry: Option<RetryPolicy>,
    pub compensate: Option<Compensation>,
    /// Earlier steps this one also waits for, on top of what precedes it (e.g. a sibling in a `parallel` group).
    pub after: Vec<String>,
    /// How long one attempt may run; a timed-out attempt is retried by the policy.
    pub timeout_ms: Option<u64>,
    /// How long the handler may go without calling `ctx.heartbeat()` (at least 1000).
    pub heartbeat_ms: Option<u64>,
    /// How long the step may wait for a worker to take it (at least 1000).
    pub schedule_to_start_ms: Option<u64>,
    /// A reference (`input`, `output`, `reference`): the step runs only when it is truthy (not null, false or "");
    /// otherwise it is skipped and later references to its output are null.
    pub only_if: Option<Value>,
    /// Runs the node only on one side of a change (`Workflow::change`, `gate`); otherwise it is skipped.
    pub gate: Option<Gate>,
}

impl Default for StepOptions {
    fn default() -> Self {
        StepOptions { input: Value::Null, retry: None, compensate: None, after: vec![], timeout_ms: None, heartbeat_ms: None, schedule_to_start_ms: None, only_if: None, gate: None }
    }
}

/// Options of a `wait_for` or `timer` node (`Workflow::wait_for_with`, `Workflow::timer_with`), enforced by the engine.
pub struct WaitOptions {
    /// Earlier steps this node also waits for, on top of what precedes it.
    pub after: Vec<String>,
    /// A reference: the node waits only when it is truthy; otherwise it is skipped.
    pub only_if: Option<Value>,
    /// Undoes the wait when the run fails after it completed (activity `<workflow>/<node>/compensate`); its input
    /// defaults to the node's output (the signal's payload, or the timer's `{timer, fired_at}`).
    pub compensate: Option<Compensation>,
    /// Runs the node only on one side of a change (`Workflow::change`, `gate`); otherwise it is skipped.
    pub gate: Option<Gate>,
}

impl Default for WaitOptions {
    fn default() -> Self {
        WaitOptions { after: vec![], only_if: None, compensate: None, gate: None }
    }
}

/// Options of a `child` node (`Workflow::child_with`), enforced by the engine. There is no `retry` or `timeout_ms`:
/// the engine does not retry or time out a child (give the child workflow's steps retries, the child a `timeout_ms`).
pub struct ChildOptions {
    /// The child run's input, resolved by the engine: a reference, or objects and arrays of references (a literal
    /// value panics when the blueprint is built). `None` passes the parent run's input.
    pub input: Option<Value>,
    /// Undoes the child when the parent run fails after it completed; its input defaults to the child's output.
    pub compensate: Option<Compensation>,
    /// Earlier steps the child also waits for, on top of what precedes it.
    pub after: Vec<String>,
    /// A reference: the child starts only when it is truthy; otherwise it is skipped.
    pub only_if: Option<Value>,
    /// Runs the node only on one side of a change (`Workflow::change`, `gate`); otherwise it is skipped.
    pub gate: Option<Gate>,
}

impl Default for ChildOptions {
    fn default() -> Self {
        ChildOptions { input: None, compensate: None, after: vec![], only_if: None, gate: None }
    }
}

/// The workflow a `child` node starts: a `Workflow` (by its name) or a workflow name (any registered one, SDK or
/// Crystal).
pub trait ChildWorkflow {
    fn workflow_name(&self) -> String;
}

impl ChildWorkflow for &str {
    fn workflow_name(&self) -> String {
        self.to_string()
    }
}

impl ChildWorkflow for String {
    fn workflow_name(&self) -> String {
        self.clone()
    }
}

impl ChildWorkflow for &Workflow {
    fn workflow_name(&self) -> String {
        self.name.clone()
    }
}

/// `Workflow::continue_as_new`: when the run ends and `only_if` holds, it closes `continued_as_new` and a fresh run
/// of the workflow starts with `input`. Enforced by the engine.
#[derive(Debug, Clone, Default)]
pub struct ContinueAsNew {
    /// The next run's input: references only (as `ChildOptions::input`); the same input when `None`.
    pub input: Option<Value>,
    /// A reference: continue only when it is truthy; always when `None`.
    pub only_if: Option<Value>,
    /// At most this many runs in the chain.
    pub max_runs: Option<u64>,
    /// Continue once the run's history holds this many events.
    pub max_events: Option<u64>,
}

/// Puts a node on one side of a change (versioning, `Workflow::change`): the node runs only for runs whose version
/// of `change` is within `min..=max` (open ended where `None`), and is skipped otherwise. A fresh run takes the
/// change's `max`. Made with `gate`.
#[derive(Debug, Clone)]
pub struct Gate {
    pub change: String,
    pub min: Option<u64>,
    pub max: Option<u64>,
}

/// A `Gate` on `change` (`StepOptions::gate`, `WaitOptions::gate`, `ChildOptions::gate`). Panics when neither bound
/// is given.
pub fn gate(change: impl Into<String>, min: Option<u64>, max: Option<u64>) -> Gate {
    let change = change.into();
    assert!(min.is_some() || max.is_some(), "gate on {:?} needs a min or a max", change);
    Gate { change, min, max }
}

impl Gate {
    fn blueprint(&self) -> Value {
        let mut out = json!({"change": self.change});
        if let Some(v) = self.min {
            out["min"] = json!(v);
        }
        if let Some(v) = self.max {
            out["max"] = json!(v);
        }
        out
    }
}

/// Options of a cancellation scope (`Workflow::scope_with`), enforced by the engine.
#[derive(Debug, Clone, Default)]
pub struct ScopeOptions {
    /// Cancel the scope this long after its first step started (the run goes on).
    pub timeout_ms: Option<u64>,
    /// Cleanup that still runs when the workflow is cancelled, times out or fails; it cannot have a `timeout_ms`.
    pub non_cancellable: bool,
}

/// An update handler of a workflow (`Workflow::update`), sent with `JoobQClient::update_workflow`; enforced by the
/// engine. `UpdateOptions::handler(f)` gives one with a handler, `UpdateOptions::default()` one without.
pub struct UpdateOptions {
    /// Runs as the activity `<workflow>/@update/<name>` and returns the update's result. It gets the task's payload
    /// as is (`input`, resolved by the engine), not retried, within `timeout_ms` (default 30 s).
    pub handler: Option<Handler>,
    /// A reference (e.g. `update_input(Some("name"))`) that must be truthy, or the update is rejected with `message`.
    pub validate: Option<Value>,
    /// The rejection's message when `validate` is not truthy.
    pub message: Option<String>,
    /// The handler's payload: references only (as `ChildOptions::input`), `${update.input}` when `None`.
    pub input: Option<Value>,
    /// Without a handler, the result: references only, `${update.input}` when `None`.
    pub result: Option<Value>,
    /// How long the handler may run.
    pub timeout_ms: Option<u64>,
}

impl Default for UpdateOptions {
    fn default() -> Self {
        UpdateOptions { handler: None, validate: None, message: None, input: None, result: None, timeout_ms: None }
    }
}

impl UpdateOptions {
    /// Options with `handler` as the update's handler (the rest default).
    pub fn handler<F>(handler: F) -> Self
    where
        F: Fn(Value, &ExecutionContext) -> Result<Value> + Send + Sync + 'static,
    {
        UpdateOptions { handler: Some(Arc::new(handler)), ..Default::default() }
    }

    fn blueprint(&self, name: &str) -> Value {
        let mut spec = json!({});
        if self.handler.is_some() {
            spec["handler"] = json!(true);
        }
        if let Some(v) = &self.validate {
            spec["validate"] = v.clone();
        }
        if let Some(m) = self.message.as_ref().filter(|m| !m.is_empty()) {
            spec["message"] = json!(m);
        }
        if let Some(i) = &self.input {
            spec["input"] = template(i, &format!("update {}.input", name));
        }
        if let Some(r) = &self.result {
            spec["result"] = template(r, &format!("update {}.result", name));
        }
        if let Some(t) = self.timeout_ms {
            spec["timeout_ms"] = json!(t);
        }
        spec
    }
}

struct StepLimits {
    timeout_ms: Option<u64>,
    heartbeat_ms: Option<u64>,
    schedule_to_start_ms: Option<u64>,
}

/// What every runnable node may carry besides its kind: `after`, `only_if`, `compensate` and `gate`.
struct NodeExtras {
    after: Vec<String>,
    only_if: Option<Value>,
    compensate: Option<Compensation>,
    gate: Option<Gate>,
}

impl NodeExtras {
    /// Adds `after`, `only_if`, `gate` and `compensate` (its references, its input defaulting to the node's output).
    fn apply(&self, name: &str, mut node: Value) -> Value {
        if !self.after.is_empty() {
            node["after"] = json!(self.after);
        }
        if let Some(c) = &self.compensate {
            let mut crefs = vec![];
            collect_references(&c.input.clone().unwrap_or_else(|| output(name, None)), &mut crefs);
            node["compensate"] = json!({"activity": Value::Null, "references": crefs});
        }
        if let Some(cond) = &self.only_if {
            node["only_if"] = cond.clone();
        }
        if let Some(g) = &self.gate {
            node["gate"] = g.blueprint();
        }
        node
    }
}

enum Node {
    Step { name: String, handler: Handler, input: Value, retry: Option<RetryPolicy>, limits: StepLimits, extras: NodeExtras },
    WaitFor { name: String, signal: String, timeout_ms: u64, extras: NodeExtras },
    Timer { name: String, duration_ms: u64, extras: NodeExtras },
    Child { name: String, workflow: String, input: Option<Value>, extras: NodeExtras },
    Group { name: String, parallel: bool, children: Vec<Node> },
    Scope { name: String, options: ScopeOptions, children: Vec<Node> },
}

fn retry_blueprint(r: &RetryPolicy) -> Value {
    let mut out = json!({"attempts": r.attempts, "initial_ms": r.initial_ms, "backoff": r.backoff, "maximum_ms": r.maximum_ms});
    if !r.non_retryable.is_empty() {
        out["non_retryable"] = json!(r.non_retryable);
    }
    out
}

impl Node {
    fn blueprint(&self) -> Value {
        match self {
            Node::Step { name, input, retry, limits, extras, .. } => {
                let mut refs = vec![];
                if input.is_null() {
                    refs.push("${input}".to_string());
                } else {
                    collect_references(input, &mut refs);
                }
                let mut node = json!({"name": name, "kind": "step", "activity": Value::Null, "references": refs});
                for (key, value) in [("timeout_ms", limits.timeout_ms), ("heartbeat_ms", limits.heartbeat_ms), ("schedule_to_start_ms", limits.schedule_to_start_ms)] {
                    if let Some(v) = value {
                        node[key] = json!(v);
                    }
                }
                if let Some(r) = retry {
                    node["retry"] = retry_blueprint(r);
                }
                extras.apply(name, node)
            }
            Node::WaitFor { name, signal, timeout_ms, extras } => extras.apply(name, json!({"name": name, "kind": "wait_for", "signal": signal, "timeout_ms": timeout_ms})),
            Node::Timer { name, duration_ms, extras } => extras.apply(name, json!({"name": name, "kind": "timer", "for_ms": duration_ms})),
            Node::Child { name, workflow, input, extras } => {
                let mut node = json!({"name": name, "kind": "child", "workflow": workflow});
                if let Some(i) = input {
                    node["input"] = template(i, &format!("{}.input", name));
                }
                extras.apply(name, node)
            }
            Node::Group { name, parallel, children } => json!({
                "name": name, "kind": if *parallel { "parallel" } else { "sequence" },
                "children": children.iter().map(|c| c.blueprint()).collect::<Vec<_>>(),
            }),
            Node::Scope { name, options, children } => {
                let mut node = json!({"name": name, "kind": "scope", "children": children.iter().map(|c| c.blueprint()).collect::<Vec<_>>()});
                if let Some(t) = options.timeout_ms {
                    node["timeout_ms"] = json!(t);
                }
                if options.non_cancellable {
                    node["non_cancellable"] = json!(true);
                }
                node
            }
        }
    }
}

/// A code-first workflow, the same DSL as `JoobQPro::Workflows::DSL` (step, wait_for, timer, child, parallel,
/// sequence, scope, continue_as_new, change, update).
pub struct Workflow {
    pub name: String,
    pub version: u32,
    /// The whole run's deadline (the run ends `timed_out`), enforced by the engine; none by default.
    pub timeout_ms: Option<u64>,
    pub task_queue: String,
    pub queries: HashMap<String, Value>,
    nodes: Vec<Node>,
    declared: HashSet<String>,
    continuation: Option<Value>,
    /// Declared changes, in order: (id, min, max).
    changes: Vec<(String, u64, u64)>,
    updates: Vec<(String, UpdateOptions)>,
    /// Built inside a scope (directly or through a group): scopes do not nest.
    in_scope: bool,
}

impl Workflow {
    pub fn new(name: impl Into<String>) -> Self {
        Workflow { name: name.into(), version: 1, timeout_ms: None, task_queue: "workflows".into(), queries: HashMap::new(), nodes: vec![], declared: HashSet::new(), continuation: None, changes: vec![], updates: vec![], in_scope: false }
    }

    pub fn version(mut self, version: u32) -> Self {
        self.version = version;
        self
    }

    /// The whole run's deadline: the engine ends the run `timed_out` after it. None by default.
    pub fn timeout_ms(mut self, timeout_ms: u64) -> Self {
        self.timeout_ms = Some(timeout_ms);
        self
    }

    pub fn task_queue(mut self, queue: impl Into<String>) -> Self {
        self.task_queue = queue.into();
        self
    }

    /// The workflow's structure as data, as the worker registers it with the gateway (`CONTRACT.md`).
    pub fn to_blueprint(&self) -> Value {
        let mut blueprint = json!({
            "name": self.name, "version": self.version, "task_queue": self.task_queue,
            "queries": self.queries, "nodes": self.nodes.iter().map(|n| n.blueprint()).collect::<Vec<_>>(),
        });
        if let Some(t) = self.timeout_ms {
            blueprint["timeout_ms"] = json!(t);
        }
        if let Some(c) = &self.continuation {
            blueprint["continue_as_new"] = c.clone();
        }
        if !self.changes.is_empty() {
            blueprint["changes"] = json!(self.changes.iter().map(|(id, min, max)| json!({"id": id, "min": min, "max": max})).collect::<Vec<_>>());
        }
        if !self.updates.is_empty() {
            let mut updates = Map::new();
            for (name, options) in &self.updates {
                updates.insert(name.clone(), options.blueprint(name));
            }
            blueprint["updates"] = Value::Object(updates);
        }
        blueprint
    }

    /// When the run ends (and `options.only_if` is truthy), it closes `continued_as_new` and a fresh run of this
    /// workflow starts with `options.input` (references only, resolved by the engine; the same input when `None`),
    /// at most `max_runs` runs. Panics on a literal input or an `only_if` that is not a reference.
    pub fn continue_as_new(mut self, options: ContinueAsNew) -> Self {
        let mut policy = json!({});
        if let Some(i) = &options.input {
            policy["input"] = template(i, "continue_as_new.input");
        }
        if let Some(cond) = &options.only_if {
            assert!(is_reference(cond), "continue_as_new: only_if must be a reference (input, output, reference), not {}", cond);
            policy["only_if"] = cond.clone();
        }
        if let Some(n) = options.max_runs {
            policy["max_runs"] = json!(n);
        }
        if let Some(n) = options.max_events {
            policy["max_events"] = json!(n);
        }
        self.continuation = Some(policy);
        self
    }

    /// Declares a change (versioning, like Temporal's getVersion): a run's version of it is fixed when it first
    /// reaches a gated node, a fresh run taking `max` (the usual first declaration is `change(id, 0, 1)`). Nodes pick a
    /// side with `gate: Some(gate(id, min, max))`. Raise `min` only once no open run is on an older path. Panics when
    /// `min` is above `max`.
    pub fn change(mut self, id: impl Into<String>, min: u64, max: u64) -> Self {
        let id = id.into();
        assert!(min <= max, "change {:?} in workflow {:?}: min is above max", id, self.name);
        match self.changes.iter_mut().find(|(c, _, _)| *c == id) {
            Some(c) => *c = (id, min, max),
            None => self.changes.push((id, min, max)),
        }
        self
    }

    /// An update handler (`JoobQClient::update_workflow`): `options.validate` (a reference, e.g.
    /// `update_input(Some("name"))`) must be truthy or the update is rejected with `options.message`; then the handler
    /// runs as a step of the run (its payload is `options.input`, by default the update's input, and its return value is
    /// the result), or, without one, `options.result` (references only) is the result. References may read the run
    /// (`input`, `output`) and `update_input`. Panics on a duplicate name, a `validate` that is not a reference, or a
    /// literal in `input` or `result`.
    pub fn update(mut self, name: impl Into<String>, options: UpdateOptions) -> Self {
        let name = name.into();
        assert!(!self.updates.iter().any(|(n, _)| *n == name), "duplicate update {:?} in workflow {:?}", name, self.name);
        if let Some(v) = &options.validate {
            assert!(is_reference(v), "update {:?}: validate must be a reference (update_input, input, output, reference), not {}", name, v);
        }
        options.blueprint(&name); // checks input and result are templates
        self.updates.push((name, options));
        self
    }

    pub fn query(mut self, name: impl Into<String>, expr: Value) -> Self {
        self.queries.insert(name.into(), expr);
        self
    }

    fn declare(&mut self, name: &str, input: &Value, after: &[String]) {
        for d in after {
            assert!(d != name && self.declared.contains(d), "step {:?} waits (after) for unknown or later step {:?}", name, d);
        }
        assert!(self.declared.insert(name.to_string()), "duplicate step {:?} in workflow {:?}", name, self.name);
        let mut deps = vec![];
        step_dependencies(input, &mut deps);
        for d in deps {
            assert!(d == name || self.declared.contains(&d), "step {:?} references unknown or later step {:?}", name, d);
        }
    }

    /// Checks a node's `only_if`: a reference, to the input or to earlier steps only.
    fn check_condition(&self, name: &str, only_if: &Option<Value>) {
        if let Some(cond) = only_if {
            assert!(is_reference(cond), "step {:?} in workflow {:?}: only_if must be a reference (input, output, reference), not {}", name, self.name, cond);
            let mut deps = vec![];
            step_dependencies(cond, &mut deps);
            for d in deps {
                assert!(d != name && self.declared.contains(&d), "step {:?}: only_if refers to unknown or later step {:?}", name, d);
            }
        }
    }

    /// A step that gets the workflow input.
    pub fn step<F>(self, name: impl Into<String>, handler: F) -> Self
    where
        F: Fn(Value, &ExecutionContext) -> Result<Value> + Send + Sync + 'static,
    {
        self.step_with(name, handler, StepOptions::default())
    }

    pub fn step_with<F>(mut self, name: impl Into<String>, handler: F, options: StepOptions) -> Self
    where
        F: Fn(Value, &ExecutionContext) -> Result<Value> + Send + Sync + 'static,
    {
        let name = name.into();
        self.check_condition(&name, &options.only_if);
        self.declare(&name, &options.input, &options.after);
        let limits = StepLimits { timeout_ms: options.timeout_ms, heartbeat_ms: options.heartbeat_ms, schedule_to_start_ms: options.schedule_to_start_ms };
        let extras = NodeExtras { after: options.after, only_if: options.only_if, compensate: options.compensate, gate: options.gate };
        self.nodes.push(Node::Step { name, handler: Arc::new(handler), input: options.input, retry: options.retry, limits, extras });
        self
    }

    /// A durable wait for a signal; its output is the signal's payload.
    pub fn wait_for(self, name: impl Into<String>, signal: impl Into<String>, timeout_ms: u64) -> Self {
        self.wait_for_with(name, signal, timeout_ms, WaitOptions::default())
    }

    /// `wait_for` with options (`after`: earlier steps it also waits for; `only_if`; `compensate`, whose input
    /// defaults to the signal's payload).
    pub fn wait_for_with(mut self, name: impl Into<String>, signal: impl Into<String>, timeout_ms: u64, options: WaitOptions) -> Self {
        let name = name.into();
        self.check_condition(&name, &options.only_if);
        self.declare(&name, &Value::Null, &options.after);
        let extras = NodeExtras { after: options.after, only_if: options.only_if, compensate: options.compensate, gate: options.gate };
        self.nodes.push(Node::WaitFor { name, signal: signal.into(), timeout_ms, extras });
        self
    }

    /// A durable wait for a time.
    pub fn timer(self, name: impl Into<String>, duration_ms: u64) -> Self {
        self.timer_with(name, duration_ms, WaitOptions::default())
    }

    /// `timer` with options (`after`: earlier steps it also waits for; `only_if`; `compensate`, whose input
    /// defaults to the timer's output).
    pub fn timer_with(mut self, name: impl Into<String>, duration_ms: u64, options: WaitOptions) -> Self {
        let name = name.into();
        self.check_condition(&name, &options.only_if);
        self.declare(&name, &Value::Null, &options.after);
        let extras = NodeExtras { after: options.after, only_if: options.only_if, compensate: options.compensate, gate: options.gate };
        self.nodes.push(Node::Timer { name, duration_ms, extras });
        self
    }

    /// Runs another workflow (a `Workflow` or its name) as a step and waits for it; its output is the child run's
    /// output, its failure the step's. The engine starts the child with the parent run's input. A child is not
    /// retried: give the child's own steps retries, and the child workflow a `timeout_ms`. The child workflow must be
    /// registered before a run reaches this step.
    pub fn child(self, name: impl Into<String>, workflow: impl ChildWorkflow) -> Self {
        self.child_with(name, workflow, ChildOptions::default())
    }

    /// `child` with options: `input` (references only, resolved by the engine), `compensate`, `after`, `only_if`
    /// (not on itself). Panics on a literal input. Needs the engine:
    /// no handler is registered for it, and a run the worker conducts itself fails at the child.
    pub fn child_with(mut self, name: impl Into<String>, workflow: impl ChildWorkflow, options: ChildOptions) -> Self {
        let name = name.into();
        if let Some(i) = &options.input {
            template(i, &format!("{}.input", name));
        }
        self.check_condition(&name, &options.only_if);
        self.declare(&name, options.input.as_ref().unwrap_or(&Value::Null), &options.after);
        let extras = NodeExtras { after: options.after, only_if: options.only_if, compensate: options.compensate, gate: options.gate };
        self.nodes.push(Node::Child { name, workflow: workflow.workflow_name(), input: options.input, extras });
        self
    }

    /// Runs the branches built on `b` on threads; its output is {child: output}.
    pub fn parallel(self, build: impl FnOnce(Workflow) -> Workflow) -> Self {
        self.group(true, build)
    }

    /// Runs the nodes built on `b` in order; its output is {child: output}.
    pub fn sequence(self, build: impl FnOnce(Workflow) -> Workflow) -> Self {
        self.group(false, build)
    }

    /// A cancellation scope: the nodes built on `b` run in sequence and can be cancelled as a unit (from the console or
    /// API, or after `timeout_ms`) while the rest of the run goes on; a cancelled step counts as finished with a null
    /// output. A running step sees the cancel through `ctx.heartbeat()` (it answers true: stop early). Needs the engine.
    pub fn scope(self, name: impl Into<String>, build: impl FnOnce(Workflow) -> Workflow) -> Self {
        self.scope_with(name, ScopeOptions::default(), build)
    }

    /// `scope` with options: `timeout_ms`, or `non_cancellable` (cleanup that still runs when the workflow is
    /// cancelled, times out or fails). Panics on a scope inside a scope (also through a `parallel` or `sequence`),
    /// `non_cancellable` with `timeout_ms`, or a scope without steps.
    pub fn scope_with(mut self, name: impl Into<String>, options: ScopeOptions, build: impl FnOnce(Workflow) -> Workflow) -> Self {
        let name = name.into();
        assert!(!self.in_scope, "scope {:?} in workflow {:?} is inside another scope: scopes do not nest", name, self.name);
        assert!(!(options.non_cancellable && options.timeout_ms.is_some()), "scope {:?} is non_cancellable and cannot time out", name);
        let mut sub = Workflow::new(self.name.clone());
        sub.declared = self.declared.clone();
        sub.in_scope = true;
        let sub = build(sub);
        assert!(!sub.nodes.is_empty(), "scope {:?} in workflow {:?} has no steps", name, self.name);
        self.declared.extend(sub.declared);
        self.nodes.push(Node::Scope { name, options, children: sub.nodes });
        self
    }

    fn group(mut self, parallel: bool, build: impl FnOnce(Workflow) -> Workflow) -> Self {
        let mut sub = Workflow::new(self.name.clone());
        sub.declared = self.declared.clone();
        sub.in_scope = self.in_scope;
        let sub = build(sub);
        self.declared.extend(sub.declared);
        let name = format!("{}_{}", if parallel { "parallel" } else { "sequence" }, self.nodes.len() + 1);
        self.nodes.push(Node::Group { name, parallel, children: sub.nodes });
        self
    }

    /// The handlers of this workflow's steps, by the activity name the engine sends them under (`<workflow>/<step>`,
    /// compensations `<workflow>/<step>/compensate`). Each runs its step once: the engine conducts the run (it retries,
    /// compensates and waits). A step's input is resolved against the run's input (the task's payload) and the outputs
    /// of the steps that completed (the task's checkpoints). Steps in a scope are included; an update handler is
    /// `<workflow>/@update/<name>` and gets the task's payload as is (the engine resolved its input).
    pub fn activities(&self) -> HashMap<String, Handler> {
        fn visit(workflow: &str, nodes: &[Node], found: &mut HashMap<String, Handler>) {
            for node in nodes {
                let (name, extras) = match node {
                    Node::Group { children, .. } | Node::Scope { children, .. } => {
                        visit(workflow, children, found);
                        continue;
                    }
                    Node::Step { name, handler, input: spec, extras, .. } => {
                        let (handler, spec) = (handler.clone(), spec.clone());
                        found.insert(
                            activity_name(workflow, name, false),
                            Arc::new(move |workflow_input: Value, ctx: &ExecutionContext| {
                                handler(resolve_references(&spec, &workflow_input, &ctx.task.checkpoints), ctx)
                            }),
                        );
                        (name, extras)
                    }
                    // The engine runs waits, timers and child workflows itself; only their compensations are ours.
                    Node::WaitFor { name, extras, .. } | Node::Timer { name, extras, .. } | Node::Child { name, extras, .. } => (name, extras),
                };
                if let Some(c) = &extras.compensate {
                    let comp_handler = c.handler.clone();
                    let comp_spec = c.input.clone().unwrap_or_else(|| output(name, None));
                    found.insert(
                        activity_name(workflow, name, true),
                        Arc::new(move |workflow_input: Value, ctx: &ExecutionContext| {
                            comp_handler(resolve_references(&comp_spec, &workflow_input, &ctx.task.checkpoints), ctx)
                        }),
                    );
                }
            }
        }
        let mut found = HashMap::new();
        visit(&self.name, &self.nodes, &mut found);
        for (update, options) in &self.updates {
            if let Some(h) = &options.handler {
                // The engine resolved the handler's input already: the payload is passed as is.
                found.insert(update_activity_name(&self.name, update), h.clone());
            }
        }
        found
    }
}

/// The activity the engine sends an update handler of an SDK workflow under.
fn update_activity_name(workflow: &str, update: &str) -> String {
    format!("{}/@update/{}", workflow, update)
}

/// The activity the engine sends a step (or its compensation) of an SDK workflow under.
fn activity_name(workflow: &str, step: &str, compensate: bool) -> String {
    if compensate {
        format!("{}/{}/compensate", workflow, step)
    } else {
        format!("{}/{}", workflow, step)
    }
}

/// The gateway's HTTP client (`/api/v1/sdk/*`, bearer `JOOBQUI_SDK_TOKEN`).
#[derive(Clone)]
pub struct JoobQClient {
    pub gateway_url: String,
    token: String,
    agent: ureq::Agent,
    /// Milliseconds one gateway call may take, shared by the clones of this client. A worker lowers it: a call that
    /// hangs for longer than a lease would let every lease the worker holds expire while its tasks still run.
    request_timeout_ms: Arc<AtomicU64>,
    pub service_name: Option<String>,
    pub team: Option<String>,
}

impl JoobQClient {
    pub fn new(gateway_url: impl Into<String>, token: impl Into<String>) -> Self {
        // Kept-alive connections, enough for a worker's poll, ack and heartbeat threads and its handlers' enqueues.
        let agent = ureq::AgentBuilder::new()
            .timeout_connect(Duration::from_secs(10))
            .timeout(Duration::from_secs(60))
            .max_idle_connections(256)
            .max_idle_connections_per_host(64)
            .build();
        JoobQClient {
            gateway_url: gateway_url.into().trim_end_matches('/').to_string(),
            token: token.into(),
            agent,
            request_timeout_ms: Arc::new(AtomicU64::new(60_000)),
            service_name: std::env::var("JOOBQ_SERVICE_NAME").ok(),
            team: std::env::var("JOOBQ_TEAM").ok(),
        }
    }

    /// Milliseconds one gateway call may take (60 000 until a worker lowers it).
    pub fn request_timeout_ms(&self) -> u64 {
        self.request_timeout_ms.load(Ordering::SeqCst)
    }

    /// Sets how long one gateway call may take, for this client and its clones.
    pub fn set_request_timeout_ms(&self, ms: u64) {
        self.request_timeout_ms.store(ms.max(1), Ordering::SeqCst);
    }

    pub fn endpoint(&self, path: &str) -> String {
        format!("{}{}", self.gateway_url, path)
    }

    fn post(&self, path: &str, body: Value) -> Result<Value> {
        self.send("POST", path, Some(body))
    }

    fn get(&self, path: &str) -> Result<Value> {
        self.send("GET", path, None)
    }

    /// One call to the gateway: a JSON body (with its Content-Type) when there is one, none for a GET.
    fn send(&self, method: &str, path: &str, body: Option<Value>) -> Result<Value> {
        let req = self
            .agent
            .request(method, &self.endpoint(path))
            .timeout(Duration::from_millis(self.request_timeout_ms()))
            .set("Authorization", &format!("Bearer {}", self.token))
            .set("X-JoobQ-SDK", &format!("rust/{}", SDK_VERSION));
        let res = match body {
            Some(b) => req.send_json(b),
            None => req.call(),
        };
        match res {
            Ok(r) => {
                let text = r.into_string().map_err(|e| Error::new(e.to_string()).with_class("TransportError"))?;
                if text.trim().is_empty() {
                    Ok(Value::Null)
                } else {
                    Ok(serde_json::from_str(&text)?)
                }
            }
            // Whatever the body (unreadable, too large for `into_string`), a 426 is the typed error.
            Err(ureq::Error::Status(426, r)) => Err(Error::too_old(&r.into_string().unwrap_or_default())),
            Err(ureq::Error::Status(code, r)) => Err(Error::gateway(code, &r.into_string().unwrap_or_default())),
            Err(e) => Err(Error::new(e.to_string()).with_class("TransportError")),
        }
    }

    pub fn enqueue_job(&self, job: EnqueueJob) -> Result<String> {
        let res = self.post("/api/v1/sdk/jobs", serde_json::to_value(job)?)?;
        Ok(res["jid"].as_str().unwrap_or_default().to_string())
    }

    /// Enqueues a defined job now (or after `delay_ms`) with its queue, retries and sealed fields.
    pub fn enqueue(&self, job: &JobDef, payload: Value, options: EnqueueOptions) -> Result<String> {
        self.enqueue_job(Self::job(job, payload, options))
    }

    /// `enqueue_job` on a thread of its own: `join` the handle for the jid (or the error). `enqueue_job` is the call that
    /// answers only once the job is stored.
    pub fn enqueue_async(&self, job: EnqueueJob) -> thread::JoinHandle<Result<String>> {
        let client = self.clone();
        thread::spawn(move || client.enqueue_job(job))
    }

    /// Enqueues many jobs with `POST /sdk/jobs/batch` (500 per call); answers one `{jid, queue, status}` per job, in order.
    pub fn enqueue_many(&self, jobs: Vec<EnqueueJob>) -> Result<Vec<Value>> {
        let mut out = Vec::with_capacity(jobs.len());
        for chunk in jobs.chunks(500) {
            let res = self.post("/api/v1/sdk/jobs/batch", json!({ "jobs": chunk }))?;
            out.extend(res["jobs"].as_array().cloned().unwrap_or_default());
        }
        Ok(out)
    }

    /// The enqueue input of a defined job, for `enqueue_many` and `enqueue_async`.
    pub fn job(job: &JobDef, payload: Value, options: EnqueueOptions) -> EnqueueJob {
        EnqueueJob {
            queue: job.queue.clone(),
            job_type: job.name.clone(),
            payload,
            context: options.context,
            jid: options.jid,
            max_retries: job.retries,
            delay_ms: options.delay_ms,
            run_at_ms: options.run_at_ms,
            expires_ms: options.expires_ms,
            timeout_ms: options.timeout_ms,
            encrypt_fields: job.encrypted_fields.clone(),
            unique_key: options.unique_key,
            unique_ttl_ms: job.unique_ttl_ms,
            unique_mode: options.unique_mode,
        }
    }

    pub fn start_workflow(&self, name: &str, input: Value, options: StartOptions) -> Result<String> {
        let res = self.post("/api/v1/sdk/workflows", json!({
            "name": name, "input": input, "context": options.context, "id": options.id,
            "search_attributes": options.search_attributes, "build": options.build,
        }))?;
        Ok(res["id"].as_str().unwrap_or_default().to_string())
    }

    pub fn signal_workflow(&self, id: &str, name: &str, payload: Value) -> Result<bool> {
        let res = self.post(&format!("/api/v1/sdk/workflows/{}/signal", id), json!({"name": name, "payload": payload}))?;
        Ok(res["accepted"].as_bool().unwrap_or(false))
    }

    /// Sends an update to a running workflow's update handler (Pro; 402 without a licence) and waits up to `wait_ms`
    /// (100 to 30000, the server's default 10000) for its outcome: `{update_id, name, status, result, error, reason,
    /// message}`. `status` is `completed`, `rejected` (its `validate` failed: `reason`, `message`), `failed`, or
    /// `accepted` when the handler had not answered in time (the gateway's 202, not an error: send again with the same
    /// `update_id` to wait for the same update).
    pub fn update_workflow(&self, id: &str, name: &str, input: Value, update_id: Option<&str>, wait_ms: Option<u64>) -> Result<Value> {
        let mut body = json!({"name": name, "input": input});
        if let Some(u) = update_id {
            body["update_id"] = json!(u);
        }
        if let Some(w) = wait_ms {
            body["wait_ms"] = json!(w);
        }
        // ureq answers a 2xx (the 200 of an outcome, the 202 of `accepted`) as Ok: both return the body.
        self.post(&format!("/api/v1/sdk/workflows/{}/updates", path_segment(id)), body)
    }

    /// One run (Pro; 402 without a licence): `{id, name, status, closed, run, started_at, closed_at, continued_to, output,
    /// failure, attributes, queries}`. Payload fields with secret-looking names are masked, as in the console.
    pub fn describe_workflow(&self, id: &str) -> Result<Value> {
        self.get(&format!("/api/v1/sdk/workflows/{}", path_segment(id)))
    }

    /// The run at the end of the workflow's continue-as-new chain (Pro; 402 without a licence), waiting up to `wait_ms`
    /// (at most 25000) for it to close; same shape as `describe_workflow`. `closed` false means it was still open when
    /// the wait ended.
    pub fn workflow_result(&self, id: &str, wait_ms: u64) -> Result<Value> {
        self.get(&format!("/api/v1/sdk/workflows/{}/result?wait_ms={}", path_segment(id), wait_ms))
    }

    /// The run's events after `after_seq` (Pro; 402 without a licence), at most `limit` (the server's default is 200),
    /// oldest first.
    pub fn workflow_history(&self, id: &str, after_seq: i64, limit: u32) -> Result<Vec<Value>> {
        let res = self.get(&format!("/api/v1/sdk/workflows/{}/history?after_seq={}&limit={}", path_segment(id), after_seq, limit))?;
        Ok(res["items"].as_array().cloned().unwrap_or_default())
    }

    /// Asks the run a read-only question declared with `Workflow::query` (Pro; 402 without a licence); answers the result.
    pub fn query_workflow(&self, id: &str, name: &str) -> Result<Value> {
        let res = self.post(&format!("/api/v1/sdk/workflows/{}/query", path_segment(id)), json!({"name": name}))?;
        Ok(res["result"].clone())
    }

    /// Sets and/or removes search attributes of the workflow's open run (Pro; 402 without a licence); answers
    /// `{id, attributes}`.
    pub fn upsert_workflow_attributes(&self, id: &str, set: Option<Map>, remove: Option<Vec<String>>) -> Result<Value> {
        self.post(&format!("/api/v1/sdk/workflows/{}/search-attributes", path_segment(id)), json!({"set": set, "remove": remove}))
    }

    pub fn register_worker(&self, worker_id: &str, queues: &[String], concurrency: usize) -> Result<()> {
        self.post("/api/v1/sdk/workers/register", json!({
            "worker_id": worker_id, "sdk_language": "rust", "sdk_version": SDK_VERSION,
            "service_name": self.service_name, "team": self.team,
            "host": std::env::var("HOSTNAME").unwrap_or_else(|_| "worker".into()), "pid": std::process::id(),
            "task_queues": queues, "concurrency": concurrency, "delivery_mode": "poll",
        }))?;
        Ok(())
    }

    /// Sends a workflow's blueprint (`Workflow::to_blueprint`); the gateway keeps each new content hash (`created`).
    pub fn register_blueprint(&self, name: &str, blueprint: &Value, worker_id: &str) -> Result<Value> {
        self.post("/api/v1/sdk/blueprints", json!({"name": name, "sdk_language": "rust", "worker_id": worker_id, "blueprint": blueprint}))
    }

    /// Registers a recurring job schedule (`kind: "job"`); pass exactly one of `cron`/`every`. Answers `{id, name, kind, created}`.
    pub fn register_schedule(&self, options: ScheduleOptions) -> Result<Value> {
        let body = ScheduleBody {
            name: options.name,
            kind: "job",
            cron: options.cron,
            every: options.every,
            timezone: options.timezone.unwrap_or_else(|| "UTC".into()),
            queue: options.queue,
            job_type: options.job_type,
            payload: options.payload.unwrap_or_else(|| json!({})),
            max_retries: options.max_retries.unwrap_or(3),
            encrypt_fields: options.encrypt_fields.unwrap_or_default(),
            unique_key: options.unique_key,
        };
        self.post("/api/v1/sdk/schedules", serde_json::to_value(body)?)
    }

    /// Creates a Pro batch with `POST /sdk/batches`: 1 to 1000 member jobs (without a `unique_key`) and the callback
    /// jobs of `options`. `on_failure` is enqueued at the first dead member, `on_complete` once every member completed or
    /// was dead-lettered, `on_success` then too when none was dead; each once, with `{"batch": {id, kind, total,
    /// succeeded, failed}}` merged into its payload. 402 pro_required without a Pro licence.
    pub fn create_batch(&self, jobs: Vec<EnqueueJob>, options: BatchOptions) -> Result<BatchCreated> {
        let BatchOptions { description, on_complete, on_success, on_failure, context } = options;
        let with_context = |mut job: EnqueueJob| {
            let mut merged = context.clone();
            merged.extend(job.context);
            job.context = merged;
            job
        };
        let members: Vec<EnqueueJob> = jobs.into_iter().map(with_context).collect();
        let mut body = json!({"description": description, "jobs": members});
        for (kind, callback) in [("on_complete", on_complete), ("on_success", on_success), ("on_failure", on_failure)] {
            if let Some(job) = callback {
                body[kind] = serde_json::to_value(with_context(job))?;
            }
        }
        let res = self.post("/api/v1/sdk/batches", body)?;
        Ok(serde_json::from_value(res)?)
    }

    /// A Pro batch's progress with `GET /sdk/batches/:id`.
    pub fn get_batch(&self, id: &str) -> Result<BatchStatus> {
        let res = self.get(&format!("/api/v1/sdk/batches/{}", path_segment(id)))?;
        Ok(serde_json::from_value(res)?)
    }

    /// Consumes one token for `key` from a `limit`-per-`period_ms` window; `allowed` is false when the window is spent.
    pub fn rate_limit(&self, key: &str, limit: i32, period_ms: i64) -> Result<RateLimitResult> {
        let res = self.post("/api/v1/sdk/rate-limit", json!({"key": key, "limit": limit, "period_ms": period_ms}))?;
        Ok(serde_json::from_value(res)?)
    }

    pub fn deregister_worker(&self, worker_id: &str) -> Result<()> {
        self.post(&format!("/api/v1/sdk/workers/{}/deregister", worker_id), json!({}))?;
        Ok(())
    }

    pub fn poll_tasks(&self, worker_id: &str, queues: &[String], max_tasks: usize, timeout_ms: u64, lease_ttl_ms: u64) -> Result<Vec<LeasedTask>> {
        let res = self.post("/api/v1/sdk/tasks/poll", json!({
            "worker_id": worker_id, "task_queues": queues, "max_tasks": max_tasks,
            "timeout_ms": timeout_ms, "lease_ttl_ms": lease_ttl_ms,
        }))?;
        Ok(serde_json::from_value(res["tasks"].clone()).unwrap_or_default())
    }

    pub fn heartbeat_task(&self, token: &str, worker_id: &str, lease_ttl_ms: u64) -> Result<bool> {
        let res = self.post(&format!("/api/v1/sdk/tasks/{}/heartbeat", token), json!({
            "worker_id": worker_id, "lease_ttl_ms": lease_ttl_ms,
        }))?;
        Ok(res["cancel_requested"].as_bool().unwrap_or(false))
    }

    pub fn complete_task(&self, token: &str, worker_id: &str, output: Value) -> Result<()> {
        self.post(&format!("/api/v1/sdk/tasks/{}/complete", token), json!({ "worker_id": worker_id, "output": output }))?;
        Ok(())
    }

    pub fn fail_task(&self, token: &str, worker_id: &str, error: &Error) -> Result<()> {
        let mut body = failure(error);
        body["worker_id"] = json!(worker_id);
        self.post(&format!("/api/v1/sdk/tasks/{}/fail", token), body)?;
        Ok(())
    }

    /// Settles up to 100 leases in one call (`POST /sdk/tasks/ack`). An item is `{token, outcome: "complete", output}`
    /// or `{token, outcome: "fail", ...failure(error)}`; each gets its own result.
    pub fn ack_tasks(&self, worker_id: &str, items: &[Value]) -> Result<Vec<Value>> {
        let res = self.post("/api/v1/sdk/tasks/ack", json!({ "worker_id": worker_id, "items": items }))?;
        Ok(res["results"].as_array().cloned().unwrap_or_default())
    }

    /// Renews many leases in one call (`POST /sdk/tasks/heartbeat`); `leases` are `{token}`.
    pub fn heartbeat_tasks(&self, worker_id: &str, leases: &[Value], lease_ttl_ms: u64) -> Result<Vec<Value>> {
        let res = self.post("/api/v1/sdk/tasks/heartbeat", json!({ "worker_id": worker_id, "lease_ttl_ms": lease_ttl_ms, "leases": leases }))?;
        Ok(res["leases"].as_array().cloned().unwrap_or_default())
    }
}

/// The fields that report `error` to the gateway (`fail_task`, and a `fail` item of `ack_tasks`).
pub fn failure(error: &Error) -> Value {
    let message = if error.message.is_empty() { error.class.clone() } else { error.message.chars().take(4000).collect() };
    let raw: String = format!("{}\n{}", error, error.backtrace).chars().take(4000).collect();
    json!({
        "error_class": error.class, "error_message": message, "retryable": error.retryable, "sdk_language": "rust",
        "stack_frames": error.frames(), "raw_stacktrace": raw,
    })
}

/// A workflow id as one URL path segment: every byte but the unreserved ones (`A-Z a-z 0-9 - . _ ~`) percent-encoded.
fn path_segment(value: &str) -> String {
    let mut out = String::with_capacity(value.len());
    for b in value.bytes() {
        if b.is_ascii_alphanumeric() || matches!(b, b'-' | b'.' | b'_' | b'~') {
            out.push(b as char);
        } else {
            out.push_str(&format!("%{:02X}", b));
        }
    }
    out
}

pub fn now_ms() -> i64 {
    SystemTime::now().duration_since(UNIX_EPOCH).map(|d| d.as_millis() as i64).unwrap_or(0)
}

/// Makes gateway text safe for one log line: control (C0, C1, DEL) and format characters (bidi controls, zero-width
/// ones) are dropped, every run of whitespace is one space, the ends are trimmed, and at most `max` characters are kept.
fn clean_text(text: &str, max: usize) -> String {
    let mut out = String::new();
    let (mut kept, mut space) = (0, false);
    for c in text.chars() {
        if c.is_whitespace() {
            space = kept > 0;
            continue;
        }
        if c.is_control() || is_format_char(c) {
            continue;
        }
        if space {
            if kept + 1 >= max {
                break;
            }
            out.push(' ');
            kept += 1;
            space = false;
        }
        if kept >= max {
            break;
        }
        out.push(c);
        kept += 1;
    }
    out
}

/// The largest index of at most `max` bytes that cuts `text` on a character boundary.
fn floor_char_boundary(text: &str, max: usize) -> usize {
    let mut end = text.len().min(max);
    while !text.is_char_boundary(end) {
        end -= 1;
    }
    end
}

/// Whether `code` is a JoobQ registry code: `JQ-` and 3 or 4 ASCII digits.
fn is_jq_code(code: &str) -> bool {
    code.strip_prefix("JQ-").is_some_and(|digits| (3..=4).contains(&digits.len()) && digits.bytes().all(|b| b.is_ascii_digit()))
}

/// Unicode general category Cf (format), which the standard library has no test for.
fn is_format_char(c: char) -> bool {
    matches!(c as u32,
        0x00AD | 0x0600..=0x0605 | 0x061C | 0x06DD | 0x070F | 0x0890..=0x0891 | 0x08E2 | 0x180E | 0x200B..=0x200F
        | 0x202A..=0x202E | 0x2060..=0x2064 | 0x2066..=0x206F | 0xFEFF | 0xFFF9..=0xFFFB | 0x110BD | 0x110CD
        | 0x13430..=0x1343F | 0x1BCA0..=0x1BCA3 | 0x1D173..=0x1D17A | 0xE0001 | 0xE0020..=0xE007F)
}

/// Stops a worker the gateway answers 426 `sdk_too_old`, saying so once with the server's message.
struct Halt {
    stop: Arc<AtomicBool>,
    error: Mutex<Option<Error>>,
}

impl Halt {
    /// Whether `e` is a 426 `sdk_too_old`; the first one stops the worker.
    fn on(&self, e: &Error) -> bool {
        if !e.is_sdk_too_old() {
            return false;
        }
        let mut slot = self.error.lock().unwrap();
        if slot.is_none() {
            eprintln!("{}", e.too_old_line());
            *slot = Some(e.clone());
            self.stop.store(true, Ordering::SeqCst);
        }
        true
    }

    fn error(&self) -> Option<Error> {
        self.error.lock().unwrap().clone()
    }

    fn halted(&self) -> bool {
        self.error.lock().unwrap().is_some()
    }
}

/// Every lease a running worker holds (buffered, running, or waiting for its ack), shared by its threads.
pub struct Transport {
    state: Mutex<TransportState>,
    changed: Condvar,
    beat: Mutex<bool>,
    beat_wake: Condvar,
    give_up: AtomicBool,
    beat_stop: AtomicBool,
    halt: Arc<Halt>,
}

#[derive(Default)]
struct TransportState {
    held: usize, // buffered + running
    leased: HashSet<String>,
    cancelled: HashMap<String, bool>,
}

impl Transport {
    fn new(halt: Arc<Halt>) -> Self {
        Transport {
            state: Mutex::new(TransportState::default()),
            changed: Condvar::new(),
            beat: Mutex::new(false),
            beat_wake: Condvar::new(),
            give_up: AtomicBool::new(false),
            beat_stop: AtomicBool::new(false),
            halt,
        }
    }

    fn wake_beat(&self) {
        *self.beat.lock().unwrap() = true;
        self.beat_wake.notify_all();
    }

    fn cancel_requested(&self, token: &str) -> bool {
        self.state.lock().unwrap().cancelled.get(token).copied().unwrap_or(false)
    }

    fn release(&self, token: &str) {
        let mut st = self.state.lock().unwrap();
        st.leased.remove(token);
        st.cancelled.remove(token);
    }

    fn send_acks(&self, client: &JoobQClient, worker_id: &str, batch: &[Value]) {
        let mut delay = 250u64;
        while !self.halt.halted() {
            match client.ack_tasks(worker_id, batch) {
                Ok(_) => break, // a refused item (its lease is gone) is not sent again either
                Err(e) if self.halt.on(&e) => break,
                Err(e) if e.status == Some(413) && batch.len() > 1 => {
                    // too large for one call: in halves
                    let (first, second) = batch.split_at(batch.len() / 2);
                    self.send_acks(client, worker_id, first);
                    self.send_acks(client, worker_id, second);
                    return;
                }
                Err(e) if e.status.map(|s| s < 500 && s != 429).unwrap_or(false) => {
                    eprintln!("joobq: the gateway refused {} outcomes: {}", batch.len(), e);
                    break;
                }
                Err(_) => {}
            }
            if self.give_up.load(Ordering::SeqCst) {
                break; // shutting down: the leases bring these tasks back
            }
            thread::sleep(Duration::from_millis(delay));
            delay = (delay * 2).min(5000);
        }
        for item in batch {
            self.release(item["token"].as_str().unwrap_or_default());
        }
    }

    fn heartbeat(&self, client: &JoobQClient, worker_id: &str, lease_ttl_ms: u64, register: impl Fn() -> Result<()>) {
        let every = Duration::from_millis((lease_ttl_ms / 3).max(500));
        let mut next_all = Instant::now() + every;
        let mut last_register = Instant::now();
        while !self.beat_stop.load(Ordering::SeqCst) {
            {
                let woken = self.beat.lock().unwrap();
                let wait = next_all.saturating_duration_since(Instant::now());
                let (mut woken, _) = self.beat_wake.wait_timeout_while(woken, wait, |w| !*w).unwrap();
                *woken = false;
            }
            if self.beat_stop.load(Ordering::SeqCst) {
                return;
            }
            if Instant::now() < next_all {
                continue;
            }
            let tokens: Vec<String> = self.state.lock().unwrap().leased.iter().cloned().collect();
            for chunk in tokens.chunks(500) {
                let leases: Vec<Value> = chunk.iter().map(|t| json!({"token": t})).collect();
                // A failed call is renewed with the next heartbeat.
                let renewed = match client.heartbeat_tasks(worker_id, &leases, lease_ttl_ms) {
                    Err(e) if self.halt.on(&e) => return,
                    other => other,
                };
                if let Ok(renewed) = renewed {
                    let mut st = self.state.lock().unwrap();
                    for lease in renewed {
                        let token = lease["lease_token"].as_str().unwrap_or_default().to_string();
                        if !lease["error"].is_null() {
                            st.leased.remove(&token); // gone: its outcome will be refused, nothing to renew
                        } else if st.leased.contains(&token) {
                            st.cancelled.insert(token, lease["cancel_requested"].as_bool().unwrap_or(false));
                        }
                    }
                }
            }
            next_all = Instant::now() + every;
            if last_register.elapsed() > Duration::from_secs(10) {
                if let Err(e) = register() {
                    if self.halt.on(&e) {
                        return;
                    }
                }
                last_register = Instant::now();
            }
        }
    }
}

/// In-app worker: runs up to `concurrency` jobs and workflow steps at once on threads inside the booted application,
/// and on SIGTERM/SIGINT (or `stop_handle()`) drains them, sends their outcomes and deregisters.
///
/// Its gateway calls run on threads of their own, so a handler never waits for HTTP: a poller keeps a small buffer of
/// leased tasks (free slots plus `prefetch`), an acker sends the outcomes handlers queue (`POST /sdk/tasks/ack`, up to
/// 100 per call after at most `ack_linger`, retried while the gateway is unavailable; a task stays leased until its
/// outcome is acknowledged; when `ack_buffer` outcomes wait, handlers wait), and a heartbeater renews every lease the
/// worker holds in one call (`POST /sdk/tasks/heartbeat`).
pub struct Worker {
    client: JoobQClient,
    pub worker_id: String,
    pub queues: Vec<String>,
    handlers: HashMap<String, Handler>,
    middlewares: Vec<Middleware>,
    blueprints: Vec<(String, Value)>,
    pub concurrency: usize,
    pub lease_ttl_ms: u64,
    pub poll_timeout_ms: u64,
    pub drain_timeout: Duration,
    /// Leases held beyond the free slots (default `concurrency / 2`, at least 1).
    pub prefetch: Option<usize>,
    /// Outcomes queued for the acker before handlers wait (default 4 x `concurrency`).
    pub ack_buffer: Option<usize>,
    /// How long the acker waits for more outcomes before it sends a batch (default 5 ms).
    pub ack_linger: Duration,
    stop: Arc<AtomicBool>,
    halt: Arc<Halt>,
    transport: Mutex<Option<(Arc<Transport>, SyncSender<Value>)>>,
}

impl Worker {
    pub fn new(client: JoobQClient, worker_id: impl Into<String>, queues: Vec<String>) -> Self {
        let stop = Arc::new(AtomicBool::new(false));
        Worker {
            client,
            worker_id: worker_id.into(),
            queues,
            handlers: HashMap::new(),
            middlewares: vec![],
            blueprints: vec![],
            concurrency: 4,
            lease_ttl_ms: 30_000,
            poll_timeout_ms: 5_000,
            drain_timeout: Duration::from_secs(30),
            prefetch: None,
            ack_buffer: None,
            ack_linger: Duration::from_millis(5),
            halt: Arc::new(Halt { stop: stop.clone(), error: Mutex::new(None) }),
            stop,
            transport: Mutex::new(None),
        }
    }

    fn add_queue(&mut self, q: &str) {
        if !q.is_empty() && !self.queues.iter().any(|x| x == q) {
            self.queues.push(q.to_string());
        }
    }

    pub fn register_job(mut self, job: JobDef) -> Self {
        self.add_queue(&job.queue);
        self.handlers.insert(job.name.clone(), job.handler);
        self
    }

    pub fn register_workflow(mut self, wf: Workflow) -> Self {
        self.add_queue(&wf.task_queue.clone());
        self.blueprints.push((wf.name.clone(), wf.to_blueprint()));
        // The engine conducts the workflow's runs and sends each step as its own task.
        self.handlers.extend(wf.activities());
        self
    }

    /// Adds a middleware around the handler of every task (a job, or one workflow step, once per lease) and
    /// returns the worker, so calls chain. `mw(ctx, next)`: the first one added is the outermost, the handler the
    /// innermost; `next()` runs the rest of the chain and returns its output. A middleware may run code around `next`,
    /// change its output, or not call it: what it returns is acknowledged as the task's output. A panic in a middleware fails the task like a panic in the handler.
    pub fn use_middleware<F>(mut self, mw: F) -> Self
    where
        F: Fn(&ExecutionContext, &dyn Fn() -> Result<Value>) -> Result<Value> + Send + Sync + 'static,
    {
        self.middlewares.push(Arc::new(mw));
        self
    }

    /// Runs the middlewares from `index` on, then the handler.
    fn run_chain(&self, index: usize, handler: &Handler, ctx: &ExecutionContext) -> Result<Value> {
        match self.middlewares.get(index) {
            Some(mw) => mw(ctx, &|| self.run_chain(index + 1, handler, ctx)),
            None => handler(ctx.task.payload.clone(), ctx),
        }
    }

    /// Set it to true to make `run` stop polling and return after the running tasks.
    pub fn stop_handle(&self) -> Arc<AtomicBool> {
        self.stop.clone()
    }

    pub fn process_task(&self, task: LeasedTask) {
        let token = task.lease_token.clone();
        let Some(handler) = self.handlers.get(&task.name).cloned() else {
            let err = Error::non_retryable(format!("No handler registered for {} [JQ-901] https://joobq.io/errors/JQ-901", task.name));
            self.settle(&token, fail_item(&err));
            return;
        };
        let mut ctx = ExecutionContext::new(task, self.worker_id.clone(), Some(self.client.clone()), self.lease_ttl_ms);
        ctx.transport = self.transport.lock().unwrap().as_ref().map(|(t, _)| t.clone());
        let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| self.run_chain(0, &handler, &ctx)))
            .unwrap_or_else(|p| Err(Error::new(p.downcast_ref::<String>().cloned().or_else(|| p.downcast_ref::<&str>().map(|s| s.to_string())).unwrap_or_else(|| "panic".into())).with_class("Panic")));
        match result {
            Ok(out) => self.settle(&token, json!({"outcome": "complete", "output": out})),
            Err(e) => self.settle(&token, fail_item(&e)),
        }
    }

    /// Hands the outcome to the acker (waiting while its queue is full); outside `run` it is sent here.
    fn settle(&self, token: &str, mut item: Value) {
        if self.halt.error().is_some() {
            return; // the gateway refuses this SDK: the outcome is left to the lease
        }
        item["token"] = json!(token);
        let sender = self.transport.lock().unwrap().as_ref().map(|(_, tx)| tx.clone());
        match sender {
            Some(tx) => {
                let _ = tx.send(item); // fails only when the worker gave up at shutdown: left to its lease
            }
            None => self.report(|| self.client.ack_tasks(&self.worker_id, std::slice::from_ref(&item)).map(|_| ())),
        }
    }

    /// Registers each workflow's blueprint not sent yet (first: a worker that shows up has its blueprints in; one the
    /// gateway refuses, 4xx, is logged and not sent again), then the worker.
    fn register(&self, concurrency: usize, sent: &Mutex<HashSet<String>>) -> Result<()> {
        for (name, blueprint) in &self.blueprints {
            if sent.lock().unwrap().contains(name) {
                continue;
            }
            if let Err(e) = self.client.register_blueprint(name, blueprint, &self.worker_id) {
                if e.status.map(|s| s >= 500).unwrap_or(true) || e.is_sdk_too_old() {
                    return Err(e);
                }
                eprintln!("joobq: blueprint of {} refused: {} [JQ-902] https://joobq.io/errors/JQ-902", name, e);
            }
            sent.lock().unwrap().insert(name.clone());
        }
        self.client.register_worker(&self.worker_id, &self.queues, concurrency)
    }

    /// Sends an outcome, retrying while the gateway is unavailable; a lost outcome is left to the lease.
    fn report(&self, call: impl Fn() -> Result<()>) {
        let mut delay = 250;
        for _ in 0..6 {
            match call() {
                Ok(()) => return,
                Err(e) if e.status.map(|s| s < 500).unwrap_or(false) => return,
                Err(_) => {
                    thread::sleep(Duration::from_millis(delay));
                    delay = (delay * 2).min(5000);
                }
            }
        }
    }

    /// Runs until SIGTERM/SIGINT or the stop handle, then drains the running tasks, sends their outcomes and deregisters.
    /// When the gateway answers 426 `sdk_too_old` it stops at once, without the drain (outcomes and the deregistration
    /// would be refused too: the leases bring the tasks back), and returns that error (`Error::is_sdk_too_old`).
    pub fn run(self) -> Result<()> {
        for sig in [signal_hook::consts::SIGTERM, signal_hook::consts::SIGINT] {
            let _ = signal_hook::flag::register(sig, self.stop.clone());
        }
        let me = Arc::new(self);
        // One hung call must not outlast the leases: a poll waits `poll_timeout_ms` at the gateway, and a sixth of a
        // lease on top keeps a renewal that hangs well inside the lease (10 s with the defaults).
        let bound = me.poll_timeout_ms + me.lease_ttl_ms / 6;
        if bound > 0 && me.client.request_timeout_ms() > bound {
            me.client.set_request_timeout_ms(bound);
        }
        let concurrency = me.concurrency.max(1);
        let capacity = concurrency + me.prefetch.unwrap_or((concurrency / 2).max(1));
        let sent = Arc::new(Mutex::new(HashSet::new()));
        let mut backoff = 250u64;
        while !me.stop.load(Ordering::SeqCst) {
            match me.register(concurrency, &sent) {
                Ok(()) => break,
                Err(e) if me.halt.on(&e) => return Err(e),
                Err(_) => {}
            }
            thread::sleep(Duration::from_millis(backoff));
            backoff = (backoff * 2).min(5000);
        }

        let t = Arc::new(Transport::new(me.halt.clone()));
        let (ack_tx, ack_rx) = mpsc::sync_channel::<Value>(me.ack_buffer.unwrap_or(4 * concurrency).max(1));
        *me.transport.lock().unwrap() = Some((t.clone(), ack_tx));
        let (ready_tx, ready_rx) = mpsc::channel::<LeasedTask>();
        let ready_rx = Arc::new(Mutex::new(ready_rx));
        let handlers: Vec<_> = (0..concurrency)
            .map(|_| {
                let (me, t, ready_rx) = (me.clone(), t.clone(), ready_rx.clone());
                thread::spawn(move || loop {
                    let next = ready_rx.lock().unwrap().recv();
                    let Ok(task) = next else { return };
                    if me.halt.error().is_none() {
                        me.process_task(task); // refused: a buffered task is left to its lease
                    }
                    t.state.lock().unwrap().held -= 1;
                    t.changed.notify_all();
                })
            })
            .collect();
        let (acked_tx, acked_rx) = mpsc::channel::<()>();
        {
            let (me, t) = (me.clone(), t.clone());
            let linger = me.ack_linger;
            thread::spawn(move || {
                'outer: loop {
                    if t.halt.halted() {
                        break; // the outcomes still queued would be refused too: left to their leases
                    }
                    let first = match ack_rx.recv_timeout(Duration::from_millis(100)) {
                        Ok(item) => item,
                        Err(RecvTimeoutError::Timeout) if t.give_up.load(Ordering::SeqCst) => break,
                        Err(RecvTimeoutError::Timeout) => continue,
                        Err(RecvTimeoutError::Disconnected) => break,
                    };
                    let mut batch = vec![first];
                    let deadline = Instant::now() + linger;
                    while batch.len() < 100 {
                        match ack_rx.recv_timeout(deadline.saturating_duration_since(Instant::now())) {
                            Ok(item) => batch.push(item),
                            Err(RecvTimeoutError::Timeout) => break,
                            Err(RecvTimeoutError::Disconnected) => {
                                t.send_acks(&me.client, &me.worker_id, &batch);
                                break 'outer;
                            }
                        }
                    }
                    t.send_acks(&me.client, &me.worker_id, &batch);
                }
                let _ = acked_tx.send(());
            });
        }
        let beat = {
            let (me, t, sent) = (me.clone(), t.clone(), sent.clone());
            thread::spawn(move || {
                t.heartbeat(&me.client, &me.worker_id, me.lease_ttl_ms, || {
                    if me.stop.load(Ordering::SeqCst) {
                        return Ok(());
                    }
                    me.register(concurrency, &sent)
                })
            })
        };

        backoff = 250;
        while !me.stop.load(Ordering::SeqCst) {
            let room = {
                let mut st = t.state.lock().unwrap();
                while st.held >= capacity && !me.stop.load(Ordering::SeqCst) {
                    st = t.changed.wait_timeout(st, Duration::from_millis(500)).unwrap().0;
                }
                capacity.saturating_sub(st.held)
            };
            if me.stop.load(Ordering::SeqCst) || room == 0 {
                continue;
            }
            let tasks = match me.client.poll_tasks(&me.worker_id, &me.queues, room.min(100), me.poll_timeout_ms, me.lease_ttl_ms) {
                Ok(t) => {
                    backoff = 250;
                    t
                }
                Err(e) if me.halt.on(&e) => break,
                Err(_) => {
                    thread::sleep(Duration::from_millis(backoff));
                    backoff = (backoff * 2).min(5000);
                    continue;
                }
            };
            {
                let mut st = t.state.lock().unwrap();
                st.held += tasks.len();
                for task in &tasks {
                    st.leased.insert(task.lease_token.clone());
                }
            }
            for task in tasks {
                let _ = ready_tx.send(task);
            }
        }

        // A refusal (now, or a 426 on an ack or a heartbeat during the drain) ends `run` at once: running handlers
        // finish and their outcomes are dropped (settle), the acker and the heartbeater end after their call in flight,
        // and the deregistration is not sent (it would be refused too).
        let mut ready_tx = Some(ready_tx);
        let abandon = |ready_tx: &mut Option<mpsc::Sender<LeasedTask>>, e: Error| {
            ready_tx.take();
            *me.transport.lock().unwrap() = None;
            t.give_up.store(true, Ordering::SeqCst);
            t.beat_stop.store(true, Ordering::SeqCst);
            t.wake_beat();
            Err(e)
        };
        if let Some(e) = me.halt.error() {
            return abandon(&mut ready_tx, e);
        }
        let deadline = Instant::now() + me.drain_timeout;
        {
            let mut st = t.state.lock().unwrap();
            while st.held > 0 && Instant::now() < deadline && !me.halt.halted() {
                st = t.changed.wait_timeout(st, Duration::from_millis(50)).unwrap().0;
            }
        }
        if let Some(e) = me.halt.error() {
            return abandon(&mut ready_tx, e);
        }
        ready_tx.take(); // the handlers end once the buffer is empty
        *me.transport.lock().unwrap() = None; // the acker ends once the outcomes are sent
        // Waits for the acker until `until`, in short steps so a refusal stops the wait.
        let acked = |until: Instant| loop {
            if me.halt.halted() {
                return false;
            }
            let step = until.saturating_duration_since(Instant::now()).min(Duration::from_millis(50));
            match acked_rx.recv_timeout(step) {
                Ok(()) | Err(RecvTimeoutError::Disconnected) => return true,
                Err(RecvTimeoutError::Timeout) if Instant::now() >= until => return false,
                Err(RecvTimeoutError::Timeout) => {}
            }
        };
        if !acked(deadline) && !me.halt.halted() {
            t.give_up.store(true, Ordering::SeqCst);
            acked(Instant::now() + Duration::from_secs(5));
        }
        if let Some(e) = me.halt.error() {
            return abandon(&mut ready_tx, e);
        }
        t.give_up.store(true, Ordering::SeqCst);
        t.beat_stop.store(true, Ordering::SeqCst);
        t.wake_beat();
        let _ = beat.join();
        drop(handlers);
        if let Some(e) = me.halt.error() {
            return Err(e); // a heartbeat refused while it stopped
        }
        me.client.deregister_worker(&me.worker_id)
    }
}

fn fail_item(error: &Error) -> Value {
    let mut item = failure(error);
    item["outcome"] = json!("fail");
    item
}
